debug.error_function_source:
async def act(page):
    import io, csv, os

    # Navigate to the Sales > Orders grid
    await page.goto('/index.php/admin/sales_order/')

    # Find the table cell that contains the export controls by scanning cells' inner text
    cells = page.get_by_role("cell")
    count = await cells.count()
    export_cell = None
    for i in range(count):
        txt = await cells.nth(i).inner_text()
        if "Export to" in txt:
            export_cell = cells.nth(i)
            break

    if export_cell is None:
        raise RuntimeError("Could not find export controls on Sales > Orders page")

    # Locate a combobox inside that cell and select CSV (prefer label match)
    combobox = export_cell.get_by_role("combobox")
    if await combobox.count() == 0:
        # fallback: search all comboboxes
        combobox = page.get_by_role("combobox")
    if await combobox.count() == 0:
        raise RuntimeError("No combobox found for export format")

    # Attempt to select CSV by visible label
    try:
        await combobox.nth(0).select_option(label="CSV")
    except Exception:
        # Try to find an option whose visible text contains CSV (case-insensitive)
        try:
            opts = await combobox.nth(0).all_inner_texts()
            chosen_label = None
            for o in opts:
                if "csv" in o.lower():
                    chosen_label = o.strip()
                    break
            if chosen_label is not None:
                await combobox.nth(0).select_option(label=chosen_label)
            else:
                # last resort: select the first option value that looks like CSV
                all_opts = await combobox.nth(0).evaluate("el => Array.from(el.options).map(o => ({label: o.label, value: o.value}))")
                selected_value = None
                for o in all_opts:
                    if "csv" in (o.get('label') or '').lower() or "csv" in (o.get('value') or '').lower():
                        selected_value = o.get('value')
                        break
                if selected_value is not None:
                    await combobox.nth(0).select_option(value=selected_value)
        except Exception as e:
            raise RuntimeError(f"Failed to select CSV option: {e}")

    # Find the Export button scoped to the same cell
    export_buttons = export_cell.get_by_role("button")
    export_btn = None
    for i in range(await export_buttons.count()):
        name = await export_buttons.nth(i).inner_text()
        if "Export" in name:
            export_btn = export_buttons.nth(i)
            break
    if export_btn is None:
        # fallback to page-level Export button
        page_buttons = page.get_by_role("button")
        for i in range(await page_buttons.count()):
            name = await page_buttons.nth(i).inner_text()
            if "Export" in name:
                export_btn = page_buttons.nth(i)
                break
    if export_btn is None:
        raise RuntimeError("Export button not found")

    # Trigger the download and save the file
    download_path = "sales_orders_export.csv"
    async with page.expect_download() as dl_info:
        await export_btn.click()
    download = await dl_info.value
    # Ensure unique filename if existing
    base = download_path
    idx = 1
    while os.path.exists(download_path):
        download_path = f"{os.path.splitext(base)[0]}_{idx}{os.path.splitext(base)[1]}"
        idx += 1
    await download.save_as(download_path)

    # Read and decode the CSV content
    with open(download_path, 'rb') as f:
        data = f.read()
    try:
        text = data.decode('utf-8')
    except Exception:
        text = data.decode('latin-1')

    # Parse CSV and compute completed orders per customer
    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        raise RuntimeError("Downloaded CSV is empty")

    # Normalize header names for matching
    headers_lower = [h.lower() for h in header]

    # Heuristics to find status and customer name/email columns
    status_idx = None
    customer_name_idx = None
    customer_email_idx = None
    for i, h in enumerate(headers_lower):
        if 'status' in h or 'order status' in h:
            status_idx = i
        if 'customer' in h and 'email' in h:
            customer_email_idx = i
        if 'email' == h or h.endswith('email'):
            # generic email column
            if customer_email_idx is None:
                customer_email_idx = i
        if 'customer' in h and ('name' in h or 'full' in h):
            customer_name_idx = i
        if 'billing' in h and 'name' in h and customer_name_idx is None:
            customer_name_idx = i
        if 'bill to name' in h and customer_name_idx is None:
            customer_name_idx = i

    # If both customer name and email absent, try to use 'customer' column
    if customer_name_idx is None and customer_email_idx is None:
        for i, h in enumerate(headers_lower):
            if 'customer' in h and customer_name_idx is None:
                customer_name_idx = i

    # Count completed orders per chosen identifier (prefer name column)
    counts = {}
    name_map = {}  # map identifier -> display name (prefer readable name)
    for row in reader:
        # guard: ensure row length
        if len(row) < 1:
            continue
        # get status
        status_val = ''
        if status_idx is not None and status_idx < len(row):
            status_val = row[status_idx].strip().lower()
        # determine customer key and display name
        key = None
        display = None
        if customer_name_idx is not None and customer_name_idx < len(row) and row[customer_name_idx].strip():
            key = row[customer_name_idx].strip()
            display = key
        elif customer_email_idx is not None and customer_email_idx < len(row) and row[customer_email_idx].strip():
            key = row[customer_email_idx].strip()
            display = key
        else:
            # fallback: combine any columns that look like name/email
            if len(row) >= 2:
                key = row[0].strip()
                display = key
            else:
                continue

        # Consider only completed orders (status contains 'complete')
        if 'complete' in status_val:
            counts[key] = counts.get(key, 0) + 1
            # store a readable display name if possible
            if display:
                name_map[key] = display

    if not counts:
        raise RuntimeError("No completed orders found in exported CSV or could not determine status column")

    # Find the customer with the maximum completed orders
    top_key = max(counts.keys(), key=lambda k: (counts[k], k))
    top_name = name_map.get(top_key, top_key)

    # Print the raw CSV download result (per earlier guidance we may print), then return the final answer
    print({"filename": download_path, "csv": text})

    # Return the final answer (only the name) via terminate_with_result mechanism by returning it
    return {"filename": download_path, "csv": text, "top_customer": top_name}

